DO $custom_staff_bind$
DECLARE v_ev jsonb:=nullif(current_setting('tus.human_custom_staff_bind',true),'')::jsonb;
 g record;rel mission_public_owner.release_admissions_v1;d mission_factory_owner.drafts;
 v_kind jsonb;v_runtime jsonb;observation jsonb;ready mission_factory_owner.editor_release_readiness;expected_qual text;
 p_draft uuid;p_version bigint;p_source text;v_before_protected text;v_expected jsonb;
BEGIN
 IF current_user IS DISTINCT FROM 'postgres'::name OR auth.uid() IS NOT NULL OR v_ev IS NULL OR jsonb_typeof(v_ev) IS DISTINCT FROM 'object'
 OR v_ev->>'expires_at' IS NULL OR (v_ev->>'expires_at')::timestamptz<=clock_timestamp() OR (v_ev->>'expires_at')::timestamptz>clock_timestamp()+interval '10 minutes'
 OR coalesce(v_ev->>'authority_sha256','')!~'^[0-9a-f]{64}$' OR coalesce(v_ev->>'review_sha256','')!~'^[0-9a-f]{64}$' OR nullif(btrim(v_ev->>'review_ref'),'') IS NULL
 THEN RAISE EXCEPTION 'HUMAN_CUSTOM_FINITE_ROOT_AUTHORITY_REQUIRED';END IF;
 IF (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(v_ev) k) IS DISTINCT FROM ARRAY['authority_sha256','draft_id','draft_version','expected_fixed30','expected_kind','expected_runtime','expires_at','observed_release_sha256','operation','protected_md5','review_ref','review_sha256','source_sha256']::text[]
 OR v_ev->>'operation' IS DISTINCT FROM 'bind_exact_custom_human_staff_draft'
 OR coalesce(v_ev->>'observed_release_sha256','')!~'^[0-9a-f]{64}$' OR coalesce(v_ev->>'source_sha256','')!~'^[0-9a-f]{64}$' OR coalesce(v_ev->>'protected_md5','')!~'^[0-9a-f]{32}$'
 OR jsonb_typeof(v_ev->'expected_fixed30') IS DISTINCT FROM 'object' OR jsonb_typeof(v_ev->'expected_kind') IS DISTINCT FROM 'object' OR jsonb_typeof(v_ev->'expected_runtime') IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'HUMAN_CUSTOM_STAFF_BIND_CLOSED_INPUT';END IF;
 p_draft:=(v_ev->>'draft_id')::uuid;p_version:=(v_ev->>'draft_version')::bigint;p_source:=v_ev->>'source_sha256';
 PERFORM pg_advisory_xact_lock(hashtextextended('human-custom-ordinary-release',15102026));
 SELECT * INTO STRICT g FROM mission_factory_owner.quest_fixed30_admission WHERE singleton FOR UPDATE;
 SELECT to_jsonb(ck) INTO v_kind FROM mission_factory_owner.c416_kind_admission ck WHERE singleton FOR SHARE;
 SELECT to_jsonb(cr) INTO v_runtime FROM mission_factory_owner.c444_runtime_control cr WHERE singleton FOR SHARE;
 SELECT * INTO STRICT d FROM mission_factory_owner.drafts WHERE id=p_draft FOR SHARE;
 SELECT * INTO STRICT rel FROM mission_public_owner.release_admissions_v1 WHERE release_sha256=v_ev->>'observed_release_sha256' FOR SHARE;
 IF to_jsonb(g) IS DISTINCT FROM v_ev->'expected_fixed30' OR v_kind IS DISTINCT FROM v_ev->'expected_kind' OR v_runtime IS DISTINCT FROM v_ev->'expected_runtime'
 OR g.public_enabled IS DISTINCT FROM false OR rel.public_enabled IS DISTINCT FROM false OR d.state NOT IN('draft','previewed')
 OR d.control_version IS DISTINCT FROM p_version OR d.document_sha256 IS DISTINCT FROM p_source OR mission_factory_owner.sha(d.document) IS DISTINCT FROM p_source
 OR d.document->>'content_kind' IS DISTINCT FROM 'quest_human' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(v_kind->'allowed_auth_ids') va WHERE va.value::uuid=d.author_user)
 OR mission_factory_owner.c416_kind_live_v1() IS DISTINCT FROM true OR mission_factory_owner.c444_enabled_v1() IS DISTINCT FROM true
 OR (v_kind->>'expires_at')::timestamptz IS DISTINCT FROM (v_runtime->>'expires_at')::timestamptz OR (v_runtime->>'expires_at')::timestamptz<=clock_timestamp()
 OR EXISTS(SELECT 1 FROM mission_factory_owner.publications pp WHERE pp.draft_id=p_draft AND pp.draft_version=p_version AND pp.source_sha256=p_source)
 THEN RAISE EXCEPTION 'HUMAN_CUSTOM_STAFF_BIND_ACTUAL_DRIFT';END IF;
 observation:=mission_factory_owner.human_ordinary_release_identity_v1('5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366',true);
 IF observation->>'schema_version' IS DISTINCT FROM 'human-compatible-release-identity/1' OR observation->>'observed_revision_sha256' IS DISTINCT FROM rel.release_sha256 OR mission_factory_owner.human_release_observation_valid_v1(observation,'5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366',true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'HUMAN_CUSTOM_STAFF_BIND_OBSERVATION';END IF;
 SELECT * INTO STRICT ready FROM jsonb_populate_record(NULL::mission_factory_owner.editor_release_readiness,observation);
 g.public_staff_enabled:=true;g.public_staff_draft_id:=p_draft;g.public_staff_draft_version:=p_version;g.public_staff_source_sha256:=p_source;
 g.public_staff_release_sha256:=ready.revision_sha256;g.public_staff_test_manifest_ref:=observation#>>'{observed_canonical_tuple,config,policy,custom_staff_manifest_ref}';
 SELECT allowed_auth_ids INTO g.allowed_auth_ids FROM mission_factory_owner.c416_kind_admission WHERE singleton;
 IF cardinality(g.allowed_auth_ids) IS DISTINCT FROM 2 OR array_position(g.allowed_auth_ids,NULL) IS NOT NULL OR rel.staff_evidence_ref IS DISTINCT FROM 'AUTHORIZED_TEST_MANIFEST:'||g.public_staff_test_manifest_ref THEN RAISE EXCEPTION 'HUMAN_CUSTOM_STAFF_BIND_SCOPE';END IF;
  expected_qual:=mission_factory_owner.sha(jsonb_build_object('schema_version','quest-human-public-staff-compatible-context/1','release_sha256',ready.revision_sha256,'observed_release_sha256',observation->>'observed_revision_sha256','compatibility_sha256',observation->>'compatibility_sha256',
   'db_sha256',rel.db_sha256,'edge_sha256',rel.edge_sha256,'client_sha256',rel.client_sha256,'config_sha256',rel.configuration_sha256,
   'independent_review_ref',rel.independent_review_ref,'authorized_test_manifest_ref',g.public_staff_test_manifest_ref,
   'draft_id',p_draft,'draft_version',p_version,'source_sha256',p_source,'allowed_auth_ids',g.allowed_auth_ids,
   'human_kind_request',(SELECT request_key FROM mission_factory_owner.c416_kind_admission WHERE singleton),'human_kind_review_sha256',(SELECT review_sha256 FROM mission_factory_owner.c416_kind_admission WHERE singleton),'location_id','0b85f354-9cdb-47e1-baf9-3d266bb7e06b'));


 g.public_staff_qualification_sha256:=expected_qual;
 v_expected:=to_jsonb(g);
 SELECT ((WITH targets(label,character_id) AS (VALUES ('pg_tamako','f335b077-34a1-41c3-94aa-58ec674b649b'::uuid),('master_riuji','6bceee99-974f-426b-8d92-38b43b4a4267'::uuid)), resources AS (select t.label,c.rank,c.vita,c.vita_max,c.chakra,c.chakra_max,c.exp,c.xp_lifetime,c.money,c.pool_concesso,c.unspent_points,md5(jsonb_build_array(c.taijutsu,c.ninjutsu,c.genjutsu,c.forza,c.velocita,c.mente,c.resistenza,c.fuuinjutsu,c.kekkei_genkai,c.lealta,c.via,c.fama,c.slot_extra)::text) stats_md5,(select count(*) from public.character_inventory x where x.character_id=c.id) inventory_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.item_id,x.quantity,x.created_at) order by x.id),'[]'::jsonb)::text) from public.character_inventory x where x.character_id=c.id) inventory_md5,(select count(*) from public.lesson_progress x where x.user_id=c.user_id) lesson_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.lesson_id,x.completed_at) order by x.id),'[]'::jsonb)::text) from public.lesson_progress x where x.user_id=c.user_id) lesson_md5,(select count(*) from public.character_jutsu x where x.user_id=c.user_id) jutsu_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.jutsu_id,x.source,x.learned_at) order by x.id),'[]'::jsonb)::text) from public.character_jutsu x where x.user_id=c.user_id) jutsu_md5,(select count(*) from public.character_abilities x where x.character_id=c.id) ability_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.technique_id,x.state,x.sessions_done,x.started_at,x.activated_at) order by x.id),'[]'::jsonb)::text) from public.character_abilities x where x.character_id=c.id) ability_md5,(select count(*) from public.character_perks x where x.character_id=c.id) perk_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.tipo,x.dettaglio,x.costo,x.grado_tecnica,x.created_at) order by x.id),'[]'::jsonb)::text) from public.character_perks x where x.character_id=c.id) perk_md5,(select count(*) from public.esame_prove x where x.candidate_user=c.user_id and x.stato='aperta') legacy_exam_open,(select count(*) from exam_regia_private.bindings x where x.owner_user=c.user_id and x.state<>'closed') legacy_binding_open,md5(jsonb_build_array(c.clan,c.element,c.element2,c.cercoterio,c.sigillo)::text) identity_build_md5 from targets t join public.characters c on c.id=t.character_id order by t.label) select jsonb_build_object('at',clock_timestamp(),'protected_md5',md5(jsonb_agg(to_jsonb(r) order by label)::text),'rows',count(*),'fields_per_pg',(select count(*) from jsonb_object_keys((select to_jsonb(x)-'label' from resources x limit 1)))) from resources r))->>'protected_md5' INTO v_before_protected;
 IF v_before_protected IS DISTINCT FROM v_ev->>'protected_md5' THEN RAISE EXCEPTION 'HUMAN_CUSTOM_STAFF_BIND_PROTECTED_DRIFT';END IF;
 UPDATE mission_factory_owner.quest_fixed30_admission SET public_staff_enabled=g.public_staff_enabled,public_staff_draft_id=g.public_staff_draft_id,public_staff_draft_version=g.public_staff_draft_version,public_staff_source_sha256=g.public_staff_source_sha256,public_staff_release_sha256=g.public_staff_release_sha256,public_staff_test_manifest_ref=g.public_staff_test_manifest_ref,public_staff_qualification_sha256=g.public_staff_qualification_sha256,allowed_auth_ids=g.allowed_auth_ids WHERE singleton;
 IF (SELECT to_jsonb(cg) FROM mission_factory_owner.quest_fixed30_admission cg WHERE singleton) IS DISTINCT FROM v_expected THEN RAISE EXCEPTION 'HUMAN_CUSTOM_STAFF_BIND_POST_DRIFT';END IF;
END $custom_staff_bind$; COMMIT;

BEGIN;
