SELECT set_config('tus.human_manual_renew',$rootmanual${"operation":"renew_exact_manual_staff_authoring_2","authority_sha256":"113c3d4f688d9e665511a9470d95797c7ce016e7596eeed621fa5407b7531888","expires_at":"2026-10-16T14:01:13.668537+00:00","baseline_sha256":"9df2911a6a6901dccaa861d454858d722d62ccf052892985c5703030fdf90fbf","review_sha256":"5429cf9d26182ecd199427a2e02c15b1047c9fd7ea19ddaf10f6dc82175b62b9","review_findings":{"P0":0,"P1":0,"P2":0},"lease_bound_at":"2026-10-16T13:26:00+00:00","lease_expires_at":"2026-10-16T15:26:00+00:00"}$rootmanual$,true);
