 lease_kind jsonb;lease_runtime jsonb;lease_manual jsonb;lease_g jsonb;lease_observation jsonb;lease_authority jsonb;
 lease_bound timestamptz;lease_expiry timestamptz;lease_protected text;lease_count integer;
BEGIN
 IF current_user IS DISTINCT FROM 'postgres'::name OR auth.uid() IS NOT NULL OR lease_ev IS NULL
 OR mission_factory_owner.keys_exact_v2(lease_ev,ARRAY['operation','authority_sha256','review_ref','review_sha256','expires_at','lease_bound_at','lease_expires_at','expected_release','expected_kind','expected_runtime','expected_manual','expected_fixed30','protected_md5']) IS DISTINCT FROM true
