 OR lease_ev->>'expires_at' IS NULL
 OR (lease_ev->>'expires_at')::timestamptz<=clock_timestamp()
 OR (lease_ev->>'expires_at')::timestamptz>clock_timestamp()+interval '10 minutes'
 OR coalesce(lease_ev->>'expected_release','')!~'^[0-9a-f]{64}$'
 OR lease_ev->>'expected_release' IN('0ff04ca971dc05bfd93b74409dcb6d995f7a4857a0b039192ed6030b47b7eaf3','5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366')
