 IS DISTINCT FROM (SELECT jsonb_agg(me||jsonb_build_object('staff_context_bound_at',lease_bound,'expires_at',lease_expiry) ORDER BY me->>'actor_user',me->>'release_sha256') FROM jsonb_array_elements(lease_manual) me)
 THEN RAISE EXCEPTION 'HUMAN_LEASE4_POST_SCOPE_DRIFT';END IF;
 IF mission_factory_owner.human_ordinary_release_identity_v1('5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366',true)->>'observed_revision_sha256' IS DISTINCT FROM lease_ev->>'expected_release'
 OR mission_factory_owner.human_ordinary_authority_v1((lease_g->>'public_staff_draft_id')::uuid,(lease_g->>'public_staff_draft_version')::bigint,lease_g->>'public_staff_source_sha256')->>'execution_context' IS DISTINCT FROM 'staff_simulation'
 OR mission_factory_owner.human_ordinary_authority_v1((lease_g->>'public_staff_draft_id')::uuid,(lease_g->>'public_staff_draft_version')::bigint,lease_g->>'public_staff_source_sha256')->>'qualification_sha256' IS DISTINCT FROM lease_g->>'public_staff_qualification_sha256'
